INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 14, 'theory', 'Quiz: dict and HashMap');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 14, 0, 'What does m.get(&k) return for a missing key?', '["a panic", "0", "None — a value of type Option", "Err"]', 2, 'get returns Option<&V>; in Python d[k] would raise KeyError, and d.get(k) would give None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 14, 1, 'How is a Counter-style word count written in Rust?', '["m[w] += 1", "*m.entry(w).or_insert(0) += 1", "m.count(w)", "m.insert(w, m[w] + 1)"]', 1, 'entry().or_insert(0) returns &mut to the value; the star dereferences it. There is a single key lookup.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 14, 2, 'Can you rely on HashMap iteration order the way you rely on insertion order in a Python dict?', '["yes, insertion order is preserved", "yes, ascending key order", "only for string keys", "no, the order is arbitrary and may change between runs"]', 3, 'If you need order, sort the keys, use BTreeMap, or the indexmap crate.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 14, 3, 'What happens to a string key after m.insert(k, 1)?', '["the key is moved into the map: k is no longer available", "nothing, k can still be used", "k is copied automatically", "the key turns into &str"]', 0, 'insert takes ownership. If you need the key later, pass k.clone().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 14, 4, 'Which methods give the union and intersection of sets?', '["plus and times", "merge and cut", "union and intersection", "or and and"]', 2, 'a.union(&b), a.intersection(&b), and a.difference(&b) return iterators that you collect into a new set.');
